import Link from 'next/link';
import { CustomerShoppingBagIcon } from '@/components/icons/CustomerShoppingBagIcon';

interface LogoProps {
  className?: string;
}

export default function Logo({ className = '' }: LogoProps) {
  return (
    <Link href="/" className={`flex items-center gap-2 text-xl font-bold hover:text-blue-600 transition-colors ${className}`}>
      <CustomerShoppingBagIcon className="h-5 w-5" />
      InternShop
    </Link>
  );
}
